import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Orders = () => {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    const fetchOrders = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/orders');
        const data = await response.json();
        setOrders(data);
      } catch (error) {
        console.error('Error fetching orders:', error);
      }
    };

    fetchOrders();
  }, []);

  return (
    <div>
      <h2>Available Orders</h2>
      {orders.length > 0 ? (
        orders.map((order) => (
          <div key={order._id}>
            <h3>Order ID: {order.orderId}</h3>
            <img src={order.productImage} alt={order.productName} width="200" />
            <p>Product Name: {order.productName}</p>
            <p>Product Type: {order.productType}</p>
            <p>Product Price: {order.productPrice}</p>
            <p>Product Description: {order.productDescription}</p>
            <h4>Stages:</h4>
            <ul>
              {order.status.map((stage, index) => (
                <li key={index}>
                  {stage.stage}: {stage.completed ? 'Completed' : 'Not Completed'} - {stage.description}
                </li>
              ))}
            </ul>
            <hr />
          </div>
        ))
      ) : (
        <p>No orders available</p>
      )}
    </div>
  );
};

export default Orders;
